mapper.select:
select bp.id, bp.process_id, bp.state, bp.process_model_id, bp.version, br.product_id, br.product_category_id from bm_process_version bp join bm_process br on bp.process_id = br.id and br.is_deleted = 0
and br.product_id = #{productId}
and bp.state = #{state}
and br.id = #{processId}
and bp.action_state = #{actionState}
order by bp.create_time desc

select bpv.id, bpv.process_instance_id, bpv.version, bpv.process_id, bpv.description, bp.product_id, bp.name processName, bm.name as productName, bm.code as productCode from bm_process bp join bm_process_version bpv on bp.id = bpv.process_id and bpv.is_deleted = 0 join bm_material bm on bp.product_id = bm.id and bm.is_deleted = 0 where bp.is_deleted = 0 and bpv.action_state = #{actionState}
and bm.name like concat('%',#{dto.productName},'%')
and bp.name like concat('%',#{dto.processName},'%')
and bpv.id in
#{processVersionId}
